import{_ as p,W as o,s as l,u as d,I as a,ah as r,w as t,Z as i,A as n}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const k=JSON.parse('{"title":"使用 Stratis 从命令行管理 Linux 存储 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Stratis 从命令行管理 Linux 存储 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"使用 Stratis 从命令行管理 Linux 存储 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Stratis 从命令行管理 Linux 存储 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180522 Using Stratis to manage Linux storage from the command line","title":"使用 Stratis 从命令行管理 Linux 存储","tag":"201806"},"relativePath":"201806/20180522 Using Stratis to manage Linux storage from the command line.md","filePath":"[post].md"}'),m={name:"201806/20180522 Using Stratis to manage Linux storage from the command line.md"};function u(g,s,c,h,f,b){const e=o("Link");return d(),l("div",null,[s[27]||(s[27]=a("h1",{id:"使用-stratis-从命令行管理-linux-存储",tabindex:"-1"},[t("使用 Stratis 从命令行管理 Linux 存储 "),a("a",{class:"header-anchor",href:"#使用-stratis-从命令行管理-linux-存储","aria-label":"Permalink to 使用 Stratis 从命令行管理 Linux 存储"},"​")],-1)),s[28]||(s[28]=a("blockquote",null,[a("p",null,"通过从命令行运行它，得到这个易于使用的 Linux 存储工具的主要用途。")],-1)),s[29]||(s[29]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/find-file-linux-code_magnifying_glass_zero.png?itok=E2HoPDg0",alt:""})],-1)),a("p",null,[s[4]||(s[4]=t("正如本系列的")),i(e,{href:"https://linux.cn/article-9736-1.html"},{default:n(()=>s[0]||(s[0]=[t("第一部分")])),_:1}),s[5]||(s[5]=t("和")),i(e,{href:"https://linux.cn/article-9743-1.html"},{default:n(()=>s[1]||(s[1]=[t("第二部分")])),_:1}),s[6]||(s[6]=t("中所讨论的，Stratis 是一个具有与 ")),i(e,{href:"https://en.wikipedia.org/wiki/ZFS"},{default:n(()=>s[2]||(s[2]=[t("ZFS")])),_:1}),s[7]||(s[7]=t(" 和 [Btrfs] ")),i(e,{href:"https://en.wikipedia.org/wiki/Btrfs"},{default:n(()=>s[3]||(s[3]=[t("4")])),_:1}),s[8]||(s[8]=t(" 相似功能的卷管理文件系统。在本文中，我们将介绍如何在命令行上使用 Stratis。"))]),s[30]||(s[30]=a("h3",{id:"安装-stratis",tabindex:"-1"},[t("安装 Stratis "),a("a",{class:"header-anchor",href:"#安装-stratis","aria-label":"Permalink to 安装 Stratis"},"​")],-1)),a("p",null,[s[10]||(s[10]=t("对于非开发人员，现在尝试 Stratis 最简单的方法是在 ")),i(e,{href:"https://fedoraproject.org/wiki/Releases/28/Schedule"},{default:n(()=>s[9]||(s[9]=[t("Fedora 28")])),_:1}),s[11]||(s[11]=t(" 中。"))]),s[31]||(s[31]=r(`<p>你可以用以下命令安装 Stratis 守护进程和 Stratis 命令行工具：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># dnf install stratis-cli stratisd</span></span></code></pre></div><h3 id="创建一个池" tabindex="-1">创建一个池 <a class="header-anchor" href="#创建一个池" aria-label="Permalink to 创建一个池">​</a></h3><p>Stratis 有三个概念：blockdevs、池和文件系统。 Blockdevs 是组成池的块设备，例如磁盘或磁盘分区。一旦创建池，就可以从中创建文件系统。</p><p>假设你的系统上有一个名为 <code>vdg</code> 的块设备，它目前没有被使用或挂载，你可以在它上面创建一个 Stratis 池：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># stratis pool create mypool /dev/vdg</span></span></code></pre></div><p>这假设 <code>vdg</code> 是完全清零并且是空的。如果它没有被使用，但有旧数据，则可能需要使用 <code>pool create</code> 的 <code>-force</code> 选项。如果正在使用，请勿将它用于 Stratis。</p><p>如果你想从多个块设备创建一个池，只需在 <code>pool create</code> 命令行中列出它们。你也可以稍后使用 <code>blockdev add-data</code> 命令添加更多的 blockdevs。请注意，Stratis 要求 blockdevs 的大小至少为 1 GiB。</p><h3 id="创建文件系统" tabindex="-1">创建文件系统 <a class="header-anchor" href="#创建文件系统" aria-label="Permalink to 创建文件系统">​</a></h3><p>在你创建了一个名为 <code>mypool</code> 的池后，你可以从它创建文件系统：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># stratis fs create mypool myfs1</span></span></code></pre></div><p>从 <code>mypool</code> 池创建一个名为 <code>myfs1</code> 的文件系统后，可以使用 Stratis 在 <code>/dev/stratis</code> 中创建的条目来挂载并使用它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># mkdir myfs1</span></span>
<span class="line"><span># mount /dev/stratis/mypool/myfs1 myfs1</span></span></code></pre></div><p>文件系统现在已被挂载在 <code>myfs1</code> 上并准备可以使用。</p><h3 id="快照" tabindex="-1">快照 <a class="header-anchor" href="#快照" aria-label="Permalink to 快照">​</a></h3><p>除了创建空文件系统之外，你还可以创建一个文件系统作为现有文件系统的快照：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># stratis fs snapshot mypool myfs1 myfs1-experiment</span></span></code></pre></div><p>这样做后，你可以挂载新的 <code>myfs1-experiment</code>，它将初始包含与 <code>myfs1</code> 相同的文件内容，但它可能随着文件系统的修改而改变。无论你对 <code>myfs1-experiment</code> 所做的任何更改都不会反映到 <code>myfs1</code> 中，除非你卸载了 <code>myfs1</code> 并将其销毁：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># umount myfs1</span></span>
<span class="line"><span># stratis fs destroy mypool myfs1</span></span></code></pre></div><p>然后进行快照以重新创建并重新挂载它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># stratis fs snapshot mypool myfs1-experiment myfs1</span></span>
<span class="line"><span># mount /dev/stratis/mypool/myfs1 myfs1</span></span></code></pre></div><h3 id="获取信息" tabindex="-1">获取信息 <a class="header-anchor" href="#获取信息" aria-label="Permalink to 获取信息">​</a></h3><p>Stratis 可以列出系统中的池：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># stratis pool list</span></span></code></pre></div><p>随着文件系统写入更多数据，你将看到 “Total Physical Used” 值的增加。当这个值接近 “Total Physical Size” 时要小心。我们仍在努力处理这个问题。</p><p>列出池中的文件系统：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># stratis fs list mypool</span></span></code></pre></div><p>列出组成池的 blockdevs：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># stratis blockdev list mypool</span></span></code></pre></div><p>目前只提供这些最少的信息，但它们将在未来提供更多信息。</p><h4 id="摧毁池" tabindex="-1">摧毁池 <a class="header-anchor" href="#摧毁池" aria-label="Permalink to 摧毁池">​</a></h4><p>当你了解了 Stratis 可以做什么后，要摧毁池，首先确保从它创建的所有文件系统都被卸载并销毁，然后使用 <code>pool destroy</code> 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># umount myfs1</span></span>
<span class="line"><span># umount myfs1-experiment (if you created it)</span></span>
<span class="line"><span># stratis fs destroy mypool myfs1</span></span>
<span class="line"><span># stratis fs destroy mypool myfs1-experiment</span></span>
<span class="line"><span># stratis pool destroy mypool</span></span></code></pre></div><p><code>stratis pool list</code> 现在应该显示没有池。</p><p>就是这些！有关更多信息，请参阅手册页：“man stratis”。</p><hr>`,36)),a("p",null,[s[13]||(s[13]=t("via: ")),i(e,{href:"https://opensource.com/article/18/5/stratis-storage-linux-command-line"},{default:n(()=>s[12]||(s[12]=[t("https://opensource.com/article/18/5/stratis-storage-linux-command-line")])),_:1})]),a("p",null,[s[18]||(s[18]=t("作者：")),i(e,{href:"https://opensource.com/users/agrover"},{default:n(()=>s[14]||(s[14]=[t("Andy Grover")])),_:1}),s[19]||(s[19]=t(" 选题：")),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>s[15]||(s[15]=[t("lujun9972")])),_:1}),s[20]||(s[20]=t(" 译者：")),i(e,{href:"https://github.com/geekpi"},{default:n(()=>s[16]||(s[16]=[t("geekpi")])),_:1}),s[21]||(s[21]=t(" 校对：")),i(e,{href:"https://github.com/wxy"},{default:n(()=>s[17]||(s[17]=[t("wxy")])),_:1})]),a("p",null,[s[24]||(s[24]=t("本文由 ")),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>s[22]||(s[22]=[t("LCTT")])),_:1}),s[25]||(s[25]=t(" 原创编译，")),i(e,{href:"https://linux.cn/"},{default:n(()=>s[23]||(s[23]=[t("Linux中国")])),_:1}),s[26]||(s[26]=t(" 荣誉推出"))])])}const x=p(m,[["render",u]]);export{k as __pageData,x as default};
